class DocCLI(CLI):
    ''' displays information on modules installed in Ansible libraries.
        It displays a terse listing of plugins and their short descriptions,
        provides a printout of their DOCUMENTATION strings,
        and it can create a short "snippet" which can be pasted into a playbook.  '''

    # default ignore list for detailed views
    IGNORE = ('module', 'docuri', 'version_added', 'short_description', 'now_date', 'plainexamples', 'returndocs', 'collection')
    _TTY_MACRO = re.compile(r'(?<!\w)(?:(?P<macro>[IBMUCLR])\((?P<value>[^)]+)\)|(?P<rule>HORIZONTALLINE)(?!\w))')

    def __init__(self, args):

        super(DocCLI, self).__init__(args)
        self.plugin_list = set()

    @classmethod
    def tty_ify(cls, text):
        def replace(match):
            macro = match.group('macro')
            if macro is None:
                return '\n-------------\n'

            value = match.group('value')
            if macro in ('I', 'C'):
                return "`%s'" % value
            if macro == 'B':
                return '*%s*' % value
            if macro == 'M':
                return '[%s]' % value
            if macro == 'U':
                return value

            if ',' not in value:
                return match.group(0)
            label, target = value.split(',', 1)
            if not label or not target.strip():
                return match.group(0)
            if macro == 'R':
                return label
            return '%s <%s>' % (label, target.lstrip())

        return cls._TTY_MACRO.sub(replace, text)

    @staticmethod
    def _wrap(text, width, **kwargs):
        rule = '\n-------------\n'
        if rule not in text:
            return textwrap.fill(text, width, **kwargs)
        return rule.join(textwrap.fill(part, width, **kwargs) for part in text.split(rule))

    def init_parser(self):

        coll_filter = 'A supplied argument will be used for filtering, can be a namespace or full collection name.'

        super(DocCLI, self).init_parser(
            desc="plugin documentation tool",
            epilog="See man pages for Ansible CLI options or website for tutorials https://docs.ansible.com"
        )
        opt_help.add_module_options(self.parser)
        opt_help.add_basedir_options(self.parser)

